// Enthusiastic Product Inventory System in C

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Structure to store product details
struct product {
    char name[50];
    int quantity;
    float price;
};

// Function to add a product to the inventory
void addProduct(struct product *inventory, char name[], int quantity, float price) {
    strcpy(inventory->name, name);
    inventory->quantity = quantity;
    inventory->price = price;
}

// Function to display the inventory
void displayInventory(struct product inventory[], int n) {
    for (int i = 0; i < n; i++) {
        printf("%d. %s: %d units @ $%.2f each\n", i + 1, inventory[i].name, inventory[i].quantity, inventory[i].price);
    }
}

// Function to update the quantity of a product
void updateQuantity(struct product *inventory, int quantity) {
    inventory->quantity = quantity;
}

// Function to update the price of a product
void updatePrice(struct product *inventory, float price) {
    inventory->price = price;
}

// Function to calculate the total cost of the inventory
float calculateTotalCost(struct product inventory[], int n) {
    float totalCost = 0;
    for (int i = 0; i < n; i++) {
        totalCost += inventory[i].quantity * inventory[i].price;
    }
    return totalCost;
}

int main() {
    struct product inventory[100];
    int n = 0;

    // Add products to the inventory
    addProduct(&inventory[n++], "Apple", 100, 1.50);
    addProduct(&inventory[n++], "Banana", 200, 2.50);
    addProduct(&inventory[n++], "Orange", 300, 3.50);

    // Display the inventory
    displayInventory(inventory, n);

    // Update the quantity of a product
    updateQuantity(&inventory[0], 150);

    // Update the price of a product
    updatePrice(&inventory[1], 3.00);

    // Calculate the total cost of the inventory
    float totalCost = calculateTotalCost(inventory, n);
    printf("Total cost of the inventory: $%.2f\n", totalCost);

    return 0;
}

