/*
 * Scientific Calculator
 *
 * A decentralized implementation of a scientific calculator in C.
 *
 * This program is designed to work with a remote server that provides
 * the necessary calculations. The client-side code sends a request
 * to the server, which then performs the calculation and returns
 * the result.
 *
 * This program is an example of a decentralized system, where the
 * client and server are separate and independent entities that
 * communicate with each other over a network.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

// Define the server address and port
#define SERVER_ADDRESS "127.0.0.1"
#define SERVER_PORT 1234

// Define the maximum buffer size
#define BUFFER_SIZE 1024

// Define the supported operations
#define OPERATION_ADD 1
#define OPERATION_SUBTRACT 2
#define OPERATION_MULTIPLY 3
#define OPERATION_DIVIDE 4

// Define the message types
#define MESSAGE_TYPE_REQUEST 1
#define MESSAGE_TYPE_RESPONSE 2

// Define the message structure
typedef struct {
    int type;
    int operation;
    double operand1;
    double operand2;
    double result;
} Message;

// Function to send a request to the server
void sendRequest(int sockfd, Message *message) {
    // Set the message type to request
    message->type = MESSAGE_TYPE_REQUEST;

    // Serialize the message into a buffer
    char buffer[BUFFER_SIZE];
    int buffer_size = sizeof(Message);
    memcpy(buffer, message, buffer_size);

    // Send the buffer to the server
    send(sockfd, buffer, buffer_size, 0);
}

// Function to receive a response from the server
void receiveResponse(int sockfd, Message *message) {
    // Set the message type to response
    message->type = MESSAGE_TYPE_RESPONSE;

    // Receive the buffer from the server
    char buffer[BUFFER_SIZE];
    int buffer_size = sizeof(Message);
    recv(sockfd, buffer, buffer_size, 0);

    // Deserialize the buffer into the message
    memcpy(message, buffer, buffer_size);
}

// Function to perform a calculation
double calculate(int operation, double operand1, double operand2) {
    switch (operation) {
        case OPERATION_ADD:
            return operand1 + operand2;
        case OPERATION_SUBTRACT:
            return operand1 - operand2;
        case OPERATION_MULTIPLY:
            return operand1 * operand2;
        case OPERATION_DIVIDE:
            return operand1 / operand2;
        default:
            return 0.0;
    }
}

int main() {
    // Create a socket
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        perror("Error creating socket");
        return 1;
    }

    // Set the server address and port
    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(SERVER_PORT);
    inet_pton(AF_INET, SERVER_ADDRESS, &server_addr.sin_addr);

    // Connect to the server
    if (connect(sockfd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Error connecting to server");
        return 1;
    }

    // Create a message structure
    Message message;

    // Send a request to the server
    sendRequest(sockfd, &message);

    // Receive a response from the server
    receiveResponse(sockfd, &message);

    // Print the result
    printf("Result: %f\n", message.result);

    // Close the socket
    close(sockfd);

    return 0;
}

