// A sophisticated C syntax parsing example program

#include <stdio.h>
#include <string.h>

// Function to check if a given character is a valid identifier
int is_valid_identifier(char c) {
    return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '_';
}

// Function to check if a given character is a valid symbol
int is_valid_symbol(char c) {
    return c == '+' || c == '-' || c == '*' || c == '/' || c == '=' || c == '(' || c == ')';
}

// Function to check if a given character is a valid delimiter
int is_valid_delimiter(char c) {
    return c == ' ' || c == '\t' || c == '\n';
}

// Function to check if a given character is a valid character
int is_valid_char(char c) {
    return is_valid_identifier(c) || is_valid_symbol(c) || is_valid_delimiter(c);
}

// Function to parse a C syntax expression
void parse_expression(char* expr) {
    int i = 0;
    while (expr[i] != '\0') {
        if (is_valid_identifier(expr[i])) {
            // Parse identifier
            int j = i + 1;
            while (j < strlen(expr) && is_valid_identifier(expr[j])) {
                j++;
            }
            printf("Identifier: %.*s\n", j - i, &expr[i]);
            i = j;
        } else if (is_valid_symbol(expr[i])) {
            // Parse symbol
            int j = i + 1;
            while (j < strlen(expr) && is_valid_symbol(expr[j])) {
                j++;
            }
            printf("Symbol: %.*s\n", j - i, &expr[i]);
            i = j;
        } else if (is_valid_delimiter(expr[i])) {
            // Parse delimiter
            int j = i + 1;
            while (j < strlen(expr) && is_valid_delimiter(expr[j])) {
                j++;
            }
            printf("Delimiter: %.*s\n", j - i, &expr[i]);
            i = j;
        } else {
            // Invalid character
            printf("Invalid character: %c\n", expr[i]);
            break;
        }
    }
}

int main() {
    char expr[] = "int x = 5 * (3 + 2);";
    parse_expression(expr);
    return 0;
}

