#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <sys/stat.h>
#include <string.h>

#define MAX_PROCESSES 100

int main() {
    // Get the current process ID
    pid_t pid = getpid();

    // Create a pipe to communicate with the child process
    int fds[2];
    if (pipe(fds) == -1) {
        perror("pipe");
        exit(1);
    }

    // Create a child process
    pid_t child_pid = fork();
    if (child_pid == 0) {
        // Child process
        close(fds[0]); // Close the read end of the pipe

        // Create a new process
        pid_t new_pid = fork();
        if (new_pid == 0) {
            // New process
            close(fds[1]); // Close the write end of the pipe

            // Do some work
            printf("I am a new process with PID %d\n", getpid());
            sleep(5);

            // Exit the new process
            exit(0);
        } else {
            // Parent process
            close(fds[1]); // Close the write end of the pipe

            // Wait for the new process to exit
            waitpid(new_pid, NULL, 0);

            // Exit the child process
            exit(0);
        }
    } else {
        // Parent process
        close(fds[1]); // Close the write end of the pipe

        // Read from the pipe to get the PID of the new process
        char buffer[10];
        read(fds[0], buffer, 10);
        close(fds[0]); // Close the read end of the pipe

        // Print the PID of the new process
        printf("The new process has PID %s\n", buffer);

        // Wait for the child process to exit
        waitpid(child_pid, NULL, 0);
    }

    return 0;
}

