//Falcon-180B DATASET v1.0 Category: Linked list operations ; Style: lively
#include<stdio.h>
#include<stdlib.h>

typedef struct node{
    int data;
    struct node *next;
}node;

void addNode(node **head, int data){
    node *newNode = (node *)malloc(sizeof(node));
    newNode->data = data;
    newNode->next = NULL;
    if(*head == NULL){
        *head = newNode;
    }
    else{
        node *temp = *head;
        while(temp->next!= NULL){
            temp = temp->next;
        }
        temp->next = newNode;
    }
}

void deleteNode(node **head, int data){
    node *temp = *head;
    node *prev = NULL;
    if(temp!= NULL && temp->data == data){
        *head = temp->next;
        free(temp);
        return;
    }
    while(temp!= NULL && temp->data!= data){
        prev = temp;
        temp = temp->next;
    }
    if(temp == NULL){
        return;
    }
    prev->next = temp->next;
    free(temp);
}

void displayList(node *head){
    node *temp = head;
    while(temp!= NULL){
        printf("%d ", temp->data);
        temp = temp->next;
    }
    printf("\n");
}

int main(){
    node *head = NULL;
    int choice, data;
    while(1){
        printf("Enter 1 to add a node, 2 to delete a node, 3 to display the list, 0 to exit: ");
        scanf("%d", &choice);
        switch(choice){
            case 1:
                printf("Enter the data to be added: ");
                scanf("%d", &data);
                addNode(&head, data);
                break;
            case 2:
                printf("Enter the data to be deleted: ");
                scanf("%d", &data);
                deleteNode(&head, data);
                break;
            case 3:
                displayList(head);
                break;
            case 0:
                exit(0);
            default:
                printf("Invalid choice\n");
        }
    }
    return 0;
}

//Falcon-180B DATASET v1.0 Category: Remote control Vehicle Simulation ; Style: multiplayer
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <arpa/inet.h>
#include <pthread.h>

#define MAX_CLIENTS 10
#define PORT 8080
#define BUFFER_SIZE 1024

int g_client_sockets[MAX_CLIENTS];
int g_num_clients = 0;

void *handle_client(void *arg) {
    int client_socket = *(int *)arg;
    char buffer[BUFFER_SIZE];

    while (1) {
        memset(buffer, 0, sizeof(buffer));
        if (recv(client_socket, buffer, BUFFER_SIZE, 0) <= 0) {
            break;
        }

        printf("Client %d: %s\n", client_socket, buffer);
        send(client_socket, buffer, strlen(buffer), 0);
    }

    close(client_socket);
    return NULL;
}

int main() {
    int server_socket;
    int opt = 1;
    struct sockaddr_in server_addr;
    int addrlen = sizeof(server_addr);

    if ((server_socket = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        printf("Socket creation failed\n");
        exit(EXIT_FAILURE);
    }

    if (setsockopt(server_socket, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &opt, sizeof(opt))) {
        printf("setsockopt() failed\n");
        exit(EXIT_FAILURE);
    }

    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = htonl(INADDR_ANY);
    server_addr.sin_port = htons(PORT);

    if (bind(server_socket, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        printf("Bind failed\n");
        exit(EXIT_FAILURE);
    }

    if (listen(server_socket, MAX_CLIENTS) < 0) {
        printf("Listen failed\n");
        exit(EXIT_FAILURE);
    }

    printf("Server is listening on port %d\n", PORT);

    while (1) {
        int client_socket;
        socklen_t client_size;

        if ((client_socket = accept(server_socket, (struct sockaddr *)&server_addr, &client_size)) < 0) {
            printf("Accept failed\n");
            exit(EXIT_FAILURE);
        }

        printf("Client connected on socket %d\n", client_socket);

        pthread_t thread_id;
        pthread_create(&thread_id, NULL, handle_client, (void *)&client_socket);
        g_client_sockets[g_num_clients++] = client_socket;
    }

    return 0;
}

//Falcon-180B DATASET v1.0 Category: Metadata Extractor ; Style: surrealist
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_LINE_LENGTH 1024 // Maximum length of a line

typedef struct {
    char *key;
    char *value;
} metadata_t;

int main(int argc, char *argv[]) {
    FILE *file;
    char line[MAX_LINE_LENGTH];
    metadata_t *metadata = NULL;
    int metadata_count = 0;

    // Check if the correct number of arguments were provided
    if (argc!= 2) {
        fprintf(stderr, "Usage: %s <filename>\n", argv[0]);
        return 1;
    }

    // Open the file for reading
    file = fopen(argv[1], "r");

    if (file == NULL) {
        fprintf(stderr, "Error opening file '%s'\n", argv[1]);
        return 1;
    }

    // Read the file line by line
    while (fgets(line, MAX_LINE_LENGTH, file)!= NULL) {
        // Check if the line contains metadata
        char *metadata_start = strstr(line, "<!--");
        char *metadata_end = strstr(line, "-->");

        if (metadata_start!= NULL && metadata_end!= NULL) {
            // Extract the metadata from the line
            char *metadata_value = metadata_start + strlen("<!--");
            char *metadata_key_start = metadata_value;
            char *metadata_key_end = strchr(metadata_value, ':');

            // Allocate memory for the metadata struct
            metadata_t *new_metadata = malloc(sizeof(metadata_t));

            // Copy the key and value into the metadata struct
            new_metadata->key = strndup(metadata_key_start, metadata_key_end - metadata_key_start);
            new_metadata->value = strndup(metadata_key_end + 1, metadata_end - metadata_key_end - 1);

            // Add the metadata to the list
            metadata = realloc(metadata, sizeof(metadata_t) * ++metadata_count);
            metadata[metadata_count - 1] = *new_metadata;
        }
    }

    // Print the extracted metadata
    for (int i = 0; i < metadata_count; i++) {
        printf("%s: %s\n", metadata[i].key, metadata[i].value);
    }

    // Free the allocated memory
    for (int i = 0; i < metadata_count; i++) {
        free(metadata[i].key);
        free(metadata[i].value);
    }
    free(metadata);

    fclose(file);

    return 0;
}

//Falcon-180B DATASET v1.0 Category: Task Scheduler ; Style: single-threaded
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_TASKS 10

typedef struct task {
    char name[50];
    int priority;
    time_t start_time;
    time_t end_time;
    int duration;
    int status;
} Task;

Task tasks[MAX_TASKS];
int num_tasks = 0;

void add_task(char *name, int priority, time_t start_time, time_t end_time, int duration) {
    if (num_tasks >= MAX_TASKS) {
        printf("Error: Maximum number of tasks reached.\n");
        return;
    }

    strcpy(tasks[num_tasks].name, name);
    tasks[num_tasks].priority = priority;
    tasks[num_tasks].start_time = start_time;
    tasks[num_tasks].end_time = end_time;
    tasks[num_tasks].duration = duration;
    tasks[num_tasks].status = 0;

    num_tasks++;
}

void schedule_tasks() {
    time_t current_time = time(NULL);
    for (int i = 0; i < num_tasks; i++) {
        if (tasks[i].start_time <= current_time && tasks[i].status == 0) {
            tasks[i].status = 1;
            printf("Starting task %s at %s\n", tasks[i].name, ctime(&current_time));
        } else if (tasks[i].end_time <= current_time && tasks[i].status == 1) {
            tasks[i].status = 2;
            printf("Ending task %s at %s\n", tasks[i].name, ctime(&current_time));
        }
    }
}

int main() {
    add_task("Task 1", 1, time(NULL) + 10, time(NULL) + 20, 10);
    add_task("Task 2", 2, time(NULL) + 15, time(NULL) + 30, 15);
    add_task("Task 3", 3, time(NULL) + 25, time(NULL) + 40, 15);

    while (1) {
        schedule_tasks();
        sleep(1);
    }

    return 0;
}

//Falcon-180B DATASET v1.0 Category: Rogue-like Game with Procedural Generation ; Style: excited
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_ROOMS 20
#define MAX_ROOM_SIZE 10
#define MAX_ENEMIES 10
#define MAX_ITEMS 10

typedef struct {
    int x, y;
} Point;

typedef struct {
    Point pos;
    char symbol;
} Room;

typedef struct {
    Point pos;
    char symbol;
    int health;
} Enemy;

typedef struct {
    Point pos;
    char symbol;
} Item;

void generate_room(Room* room) {
    room->pos.x = rand() % MAX_ROOM_SIZE;
    room->pos.y = rand() % MAX_ROOM_SIZE;
    room->symbol = rand() % 3 + 'A';
}

void generate_enemy(Enemy* enemy) {
    enemy->pos.x = rand() % MAX_ROOM_SIZE;
    enemy->pos.y = rand() % MAX_ROOM_SIZE;
    enemy->symbol = rand() % 3 + 'E';
    enemy->health = rand() % 10 + 1;
}

void generate_item(Item* item) {
    item->pos.x = rand() % MAX_ROOM_SIZE;
    item->pos.y = rand() % MAX_ROOM_SIZE;
    item->symbol = rand() % 3 + 'I';
}

void generate_dungeon(Room rooms[MAX_ROOMS], Enemy enemies[MAX_ENEMIES], Item items[MAX_ITEMS]) {
    srand(time(NULL));

    for (int i = 0; i < MAX_ROOMS; i++) {
        generate_room(&rooms[i]);
    }

    for (int i = 0; i < MAX_ENEMIES; i++) {
        generate_enemy(&enemies[i]);
    }

    for (int i = 0; i < MAX_ITEMS; i++) {
        generate_item(&items[i]);
    }
}

int main() {
    Room rooms[MAX_ROOMS];
    Enemy enemies[MAX_ENEMIES];
    Item items[MAX_ITEMS];

    generate_dungeon(rooms, enemies, items);

    return 0;
}

//Falcon-180B DATASET v1.0 Category: Bucket Sort Implementation ; Style: portable
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

#define MAX_SIZE 100

void bucket_sort(int arr[], int n) {
    int i, j, index, max_val = arr[0];
    int bucket[MAX_SIZE];
    for (i = 0; i < n; i++) {
        if (arr[i] > max_val) {
            max_val = arr[i];
        }
    }
    for (i = 0; i < n; i++) {
        index = arr[i] * MAX_SIZE / max_val;
        if (!bucket[index]) {
            bucket[index] = 1;
        }
        bucket[index]++;
    }
    for (i = 0; i < MAX_SIZE; i++) {
        if (bucket[i]) {
            for (j = 0; j < bucket[i]; j++) {
                arr[j * MAX_SIZE / n + i * MAX_SIZE / n] = i * MAX_SIZE / n + 1;
            }
        }
    }
}

void print_array(int arr[], int n) {
    int i;
    for (i = 0; i < n; i++) {
        printf("%d ", arr[i]);
    }
    printf("\n");
}

int main() {
    int n, i;
