#include <time.h>
#include <GL/glut.h>

#define MAX_LEVEL 10
#define NUM_SQUARES (2 * MAX_LEVEL - 1)

void drawSquare(int x, int y, int size) {
    glBegin(GL_QUADS);
    glVertex2i(x, y);
    glVertex2i(x + size, y);
    glVertex2i(x + size, y + size);
    glVertex2i(x, y + size);
    glEnd();
}

void drawFibonacci(int x, int y, int size, int level) {
    if (level == 0) {
        drawSquare(x, y, size);
    }
    else {
        int halfSize = size / 2;
        drawFibonacci(x, y, size, level - 1);
        drawFibonacci(x + halfSize, y, size, level - 1);
    }
}

void display() {
    glClear(GL_COLOR_BUFFER_BIT);
    int size = 50;
    int x = (glutGet(GLUT_WINDOW_WIDTH) - size * NUM_SQUARES) / 2;
    int y = (glutGet(GLUT_WINDOW_HEIGHT) - size) / 2;
    for (int i = 0; i < NUM_SQUARES; i++) {
        drawFibonacci(x, y, size, MAX_LEVEL - 1);
        x += size;
    }
    glFlush();
}

void init() {
