#include <stdio.h>
#include <unistd.h>
#include <stdlib.h>
#include <string.h>

int main() {
    pid_t child_pid, parent_pid;
    int pipe_read[2], pipe_write[2];
    char message[100];

    // Create pipes
    if (pipe(pipe_read) == -1 || pipe(pipe_write) == -1) {
        perror("Error creating pipes");
        return 1;
    }

    // Fork the child process
    if ((child_pid = fork()) == -1) {
        perror("Error forking");
        return 1;
    } else if (child_pid == 0) {
        // Child process
        close(pipe_read[0]);
        close(pipe_write[1]);

        // Read message from pipe
        if (read(pipe_read[1], message, sizeof(message)) == -1) {
            perror("Error reading from pipe");
            return 1;
        }

        // Send message back to parent process
        write(pipe_write[0], message, sizeof(message));
        exit(0);
    } else {
        // Parent process
        close(pipe_write[0]);
        close(pipe_read[1]);

        // Read message from pipe
        if (read(pipe_read[0], message, sizeof(message)) == -1) {
            perror("Error reading from pipe");
            return 1;
        }

        // Print message
        printf("Received message from child: %s\n", message);

        // Send message to child process
        write(pipe_write[1], message, sizeof(message));
        exit(0);
    }

    return 0;
}

