      sprintf(response, "HTTP/1.1 404 Not Found\r\nContent-Type: text/html\r\n\r\n<h1>404 Not Found</h1>");
    }

    if (send(client_fd, response, strlen(response), 0) < 0) {
      perror("send");
      close(client_fd);
      continue;
    }

    // Close the client connection
    close(client_fd);
  }

  // Close the server socket
  close(server_fd);

  return 0;
}

