#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/ipc.h>
#include <sys/msg.h>

// Message queue structure
struct msg_struct {
  long mtype;
  char mtext[100];
};

// Function for parent process
void parent(int msgid) {
  struct msg_struct msg;

  // Initialize message data
  msg.mtype = 1;
  sprintf(msg.mtext, "Hello, child!");

  // Send message to child
  msgsnd(msgid, &msg, sizeof(msg.mtext), 0);

  // Receive message from child
  msgrcv(msgid, &msg, sizeof(msg.mtext), 2, 0);

  // Print message from child
  printf("Received from child: %s\n", msg.mtext);
}

// Function for child process
void child(int msgid) {
  struct msg_struct msg;

  // Receive message from parent
  msgrcv(msgid, &msg, sizeof(msg.mtext), 1, 0);

  // Print message from parent
  printf("Received from parent: %s\n", msg.mtext);

  // Initialize message data
  msg.mtype = 2;
  sprintf(msg.mtext, "Hello, parent!");

  // Send message to parent
  msgsnd(msgid, &msg, sizeof(msg.mtext), 0);
}

int main() {
  // Create message queue
  int msgid = msgget(IPC_PRIVATE, 0666 | IPC_CREAT);
  if (msgid == -1) {
    perror("msgget");
    exit(1);
  }

  // Fork child process
  pid_t pid = fork();
  if (pid == -1) {
    perror("fork");
    exit(1);
  }

  // Parent process
  if (pid > 0) {
    parent(msgid);
  } 
  // Child process
  else {
    child(msgid);
  }

  // Remove message queue
  msgctl(msgid, IPC_RMID, NULL);

  return 0;
}

