#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <netdb.h>

#define SCAN_INTERFACE "wlan0"
#define SCAN_DURATION 5

int main()
{
    int sockfd, scan_result, bss_size, i, j;
    char bss_buffer[256];
    struct sockaddr_in bss_addr;

    // Open a socket for scanning
    sockfd = socket(AF_INET, SOCK_DGRAM, htons(1));

    // Bind the socket to the scanning interface
    if (bind(sockfd, NULL, 0) < 0)
    {
        perror("Error binding socket");
        return -1;
    }

    // Start scanning
    scan_result = 0;
    for (i = 0; i < SCAN_DURATION; i++)
    {
        // Listen for a beacon
        if (listen(sockfd, 1) < 0)
        {
            perror("Error listening for beacon");
            return -1;
        }

        // Get the BSS information
        bss_size = recvfrom(sockfd, bss_buffer, sizeof(bss_buffer), NULL, (struct sockaddr *)&bss_addr, NULL);

        // Print the BSS information
        if (bss_size > 0)
        {
            printf("BSS: %s\n", bss_buffer);
            scan_result++;
        }
    }

    // Print the number of scanned BSSs
    printf("Number of scanned BSSs: %d\n", scan_result);

    // Close the socket
    close(sockfd);

