#include <stdio.h>
#include <sys/wait.h>
#include <unistd.h>
#include <stdlib.h>
#include <string.h>

#define MAX_PROC_NAME_LEN 256

int main()
{
    char proc_name[MAX_PROC_NAME_LEN];
    FILE *fp;
    int i, pid, status;
    char buff[MAX_PROC_NAME_LEN];

    // Open a pipe to communicate with the child process
    int pipefd[2];
    pipe(pipefd);

    // Fork the child process
    pid = fork();

    // If the child process is created, execute the following code
    if (pid == 0)
    {
        // Close the read end of the pipe
        close(pipefd[0]);

        // Get the process name from the pipe
        read(pipefd[1], proc_name, MAX_PROC_NAME_LEN);

        // Print the process name
        printf("Process name: %s\n", proc_name);

        // Exit the child process
        exit(0);
    }

    // If the parent process is created, execute the following code
    else
    {
        // Close the write end of the pipe
        close(pipefd[1]);

        // Wait for the child process to complete
        wait(&status);

        // Open a file to store the process names
        fp = fopen("process_names.txt", "w");

        // Get the process name from the child process
        read(pipefd[0], proc_name, MAX_PROC_NAME_LEN);

        // Write the process name to the file
        fprintf(fp, "%s\n", proc_name);

        // Close the file
        fclose(fp);

        // Print the process name
        printf("Process name: %s\n", proc_name);
    }

    return 0;
}

