#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <netdb.h>

int main(int argc, char* argv[]) {
    if (argc != 4) {
        printf("Usage: %s <hostname> <username> <password>\n", argv[0]);
        return 1;
    }

    char* hostname = argv[1];
    char* username = argv[2];
    char* password = argv[3];

    struct hostent* host = gethostbyname(hostname);
    if (host == NULL) {
        printf("Error: cannot resolve hostname %s\n", hostname);
        return 2;
    }

    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        printf("Error: cannot create socket\n");
        return 3;
    }

    struct sockaddr_in serveraddr;
    memset(&serveraddr, 0, sizeof(serveraddr));
    serveraddr.sin_family = AF_INET;
    memcpy(&serveraddr.sin_addr.s_addr, host->h_addr, host->h_length);
    serveraddr.sin_port = htons(21);

    if (connect(sockfd, (struct sockaddr*)&serveraddr, sizeof(serveraddr)) < 0) {
        printf("Error: cannot connect to ftp server\n");
        return 4;
    }

    char buffer[256];
    recv(sockfd, buffer, sizeof(buffer), 0);
    printf("%s", buffer);

    sprintf(buffer, "USER %s\r\n", username);
    send(sockfd, buffer, strlen(buffer), 0);
    recv(sockfd, buffer, sizeof(buffer), 0);
    printf("%s", buffer);

    sprintf(buffer, "PASS %s\r\n", password);
    send(sockfd, buffer, strlen(buffer), 0);
    recv(sockfd, buffer, sizeof(buffer), 0);
    printf("%s", buffer);

    close(sockfd);
    return 0;
}

//FormAI DATASET v1.0 Category: Disk space analyzer ; Style: future-proof
#include<stdio.h>
#include<stdlib.h>
#include<dirent.h>
#include<sys/stat.h>
#include<string.h>

// Define global variables for keeping track of total disk space and individual file/folder sizes
unsigned long long disk_space = 0;
unsigned long long folder_space = 0;
unsigned long long file_space = 0;

// Function to recursively iterate over directories and files
void analyze(char *dir_path) {
    DIR *dir = opendir(dir_path);
    if (dir == NULL) {
        perror("Unable to open directory");
        exit(EXIT_FAILURE);
    }
    struct dirent *entry;
    struct stat statbuf;
    while ((entry = readdir(dir)) != NULL) {
        char path[1024];
        snprintf(path, sizeof(path), "%s/%s", dir_path, entry->d_name);
        if (lstat(path, &statbuf) == -1) {
            perror("Unable to get file status");
        }
        // Check if the entry is a directory
        if (S_ISDIR(statbuf.st_mode)) {
            if (strcmp(".", entry->d_name) == 0 || strcmp("..", entry->d_name) == 0) {
                continue;
            }
            analyze(path); // Recurse over the subdirectory
            folder_space += statbuf.st_size;
        }
        // Entry is a file
        else {
            file_space += statbuf.st_size;
        }
    }
    closedir(dir);
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        printf("Usage: %s <directory_path>\n", argv[0]);
        exit(EXIT_FAILURE);
    }
    analyze(argv[1]);
    disk_space = folder_space + file_space;
    printf("Total disk space used: %llu bytes\n", disk_space);
    printf("Total space used by folders: %llu bytes\n", folder_space);
    printf("Total space used by files: %llu bytes\n", file_space);
    return 0;
}

