#define AES_KEY_SIZE 256
#define AES_BLOCK_SIZE 16

typedef struct {
    unsigned char *input;
    unsigned char *output;
    AES_KEY *aes_key;
    int length;
} aes_task_t;

void *encrypt_task(void *arg) {
    aes_task_t *task = (aes_task_t *)arg;
    unsigned char iv[AES_BLOCK_SIZE] = {0}; // Initialization vector
    RAND_bytes(iv, sizeof(iv)); // Random IV for each encryption

    // Encrypt the input text
    AES_cfb128_encrypt(task->input, task->output, task->length, task->aes_key, iv, NULL, AES_ENCRYPT);

    pthread_exit(NULL);
}

void *decrypt_task(void *arg) {
    aes_task_t *task = (aes_task_t *)arg;
    unsigned char iv[AES_BLOCK_SIZE] = {0}; // Initialization vector
    RAND_bytes(iv, sizeof(iv)); // Random IV for decryption

    // Decrypt the input text
    AES_cfb128_encrypt(task->input, task->output, task->length, task->aes_key, iv, NULL, AES_DECRYPT);

    pthread_exit(NULL);
}

void print_hex(const char *desc, unsigned char *buf, int len) {
    printf("%s: ", desc);
    for (int i = 0; i < len; i++) {
        printf("%02x ", buf[i]);
    }
    printf("\n");
}

void handle_encryption(unsigned char *key, unsigned char *input, unsigned char *encrypted, unsigned char *decrypted, int length) {
    AES_KEY aes_encrypt_key, aes_decrypt_key;

    // Set encryption and decryption keys
    AES_set_encrypt_key(key, AES_KEY_SIZE, &aes_encrypt_key);
    AES_set_decrypt_key(key, AES_KEY_SIZE, &aes_decrypt_key);

    // Prepare tasks
    aes_task_t encrypt_task_data = {input, encrypted, &aes_encrypt_key, length};
    aes_task_t decrypt_task_data = {encrypted, decrypted, &aes_decrypt_key, length};

    pthread_t encrypt_thread, decrypt_thread;

    // Start the encryption thread
    if (pthread_create(&encrypt_thread, NULL, encrypt_task, (void *)&encrypt_task_data) != 0) {
        perror("Failed to create encryption thread");
        exit(EXIT_FAILURE);
    }

    // Start the decryption thread
    if (pthread_create(&decrypt_thread, NULL, decrypt_task, (void *)&decrypt_task_data) != 0) {
        perror("Failed to create decryption thread");
        exit(EXIT_FAILURE);
    }

    // Wait for both threads to finish
    pthread_join(encrypt_thread, NULL);
    pthread_join(decrypt_thread, NULL);
}

