#include <string.h>
#include <unistd.h>

#define MAX_BUFFER 1024
#define DEFAULT_COUNT 4
#define DEFAULT_TIMEOUT 1
#define DEFAULT_SIZE 64

void print_usage() {
    printf("Usage: ping_test <hostname> [options]\n");
    printf("Options:\n");
    printf("  -c <count>     Number of pings (default: %d)\n", DEFAULT_COUNT);
    printf("  -t <timeout>   Timeout in seconds (default: %d)\n", DEFAULT_TIMEOUT);
    printf("  -s <size>      Size of packets in bytes (default: %d)\n", DEFAULT_SIZE);
    printf("  -h             Show this help message\n");
}

void parse_arguments(int argc, char *argv[], char *hostname, int *count, int *timeout, int *size) {
    int opt;
    *count = DEFAULT_COUNT;
    *timeout = DEFAULT_TIMEOUT;
    *size = DEFAULT_SIZE;

    while ((opt = getopt(argc, argv, "c:t:s:h")) != -1) {
        switch(opt) {
            case 'c':
                *count = atoi(optarg);
                break;
            case 't':
                *timeout = atoi(optarg);
                break;
            case 's':
                *size = atoi(optarg);
                break;
            case 'h':
                print_usage();
                exit(EXIT_SUCCESS);
            default:
                print_usage();
                exit(EXIT_FAILURE);
        }
    }

    if (optind < argc) {
        strcpy(hostname, argv[optind]);
    } else {
        fprintf(stderr, "Error: hostname not specified.\n");
        print_usage();
        exit(EXIT_FAILURE);
    }
}

void execute_ping(const char *hostname, int count, int timeout, int size) {
    char command[MAX_BUFFER];
    snprintf(command, sizeof(command), "ping -c %d -W %d -s %d %s", count, timeout, size, hostname);

