        w[i] = (chunk[i * 4] << 24) | (chunk[i * 4 + 1] << 16) | (chunk[i * 4 + 2] << 8) | (chunk[i * 4 + 3]);
    }

    for (int i = 16; i < 64; ++i) {
        uint32_t s0 = ROTATE_LEFT(w[i - 15], 7) ^ ROTATE_LEFT(w[i - 15], 18) ^ (w[i - 15] >> 3);
        uint32_t s1 = ROTATE_LEFT(w[i - 2], 17) ^ ROTATE_LEFT(w[i - 2], 19) ^ (w[i - 2] >> 10);
        w[i] = w[i - 16] + s0 + w[i - 7] + s1;
    }

    uint32_t a = h[0];
    uint32_t b = h[1];
    uint32_t c = h[2];
    uint32_t d = h[3];
    uint32_t e = h[4];
    uint32_t f = h[5];
    uint32_t g = h[6];
    uint32_t h9 = h[7];

    for (int i = 0; i < 64; ++i) {
        uint32_t S1 = ROTATE_LEFT(e, 6) ^ ROTATE_LEFT(e, 11) ^ ROTATE_LEFT(e, 25);
        uint32_t ch = (e & f) ^ (~e & g);
        uint32_t temp1 = h9 + S1 + ch + k[i] + w[i];
        uint32_t S0 = ROTATE_LEFT(a, 2) ^ ROTATE_LEFT(a, 13) ^ ROTATE_LEFT(a, 22);
        uint32_t maj = (a & b) ^ (a & c) ^ (b & c);
        uint32_t temp2 = S0 + maj;

        h9 = g;
        g = f;
        f = e;
        e = d + temp1;
        d = c;
        c = b;
        b = a;
        a = temp1 + temp2;
    }

    h[0] += a;
    h[1] += b;
    h[2] += c;
    h[3] += d;
    h[4] += e;
    h[5] += f;
    h[6] += g;
    h[7] += h9;
}

void sha256(const uint8_t *message, size_t len, uint8_t *digest) {
    uint8_t chunk[64];
    size_t remaining = len;
    size_t offset = 0;

    while (remaining >= 64) {
        memcpy(chunk, message + offset, 64);
        process_chunk(chunk, 64);
        offset += 64;
        remaining -= 64;
    }

    memset(chunk, 0, 64);
    memcpy(chunk, message + offset, remaining);
    chunk[remaining] = 0x80;

    if (remaining >= 56) {
        process_chunk(chunk, 64);
        memset(chunk, 0, 64);
    }

    uint64_t bit_len = len * 8;
    chunk[56] = (bit_len >> 56) & 0xff;
    chunk[57] = (bit_len >> 48) & 0xff;
    chunk[58] = (bit_len >> 40) & 0xff;
    chunk[59] = (bit_len >> 32) & 0xff;
    chunk[60] = (bit_len >> 24) & 0xff;
    chunk[61] = (bit_len >> 16) & 0xff;
    chunk[62] = (bit_len >> 8) & 0xff;
    chunk[63] = (bit_len & 0xff);

    process_chunk(chunk, 64);

    for (int i = 0; i < 8; ++i) {
        digest[i * 4] = (h[i] >> 24) & 0xff;
        digest[i * 4 + 1] = (h[i] >> 16) & 0xff;
        digest[i * 4 + 2] = (h[i] >> 8) & 0xff;
        digest[i * 4 + 3] = (h[i] & 0xff);
    }
}

void print_hex(const uint8_t *digest) {
    for (int i = 0; i < SHA256_BLOCK_SIZE; ++i) {
        printf("%02x", digest[i]);
    }
    printf("\n");
}

int main() {
    const char *input = "In a world where trees sing and the moonlight dances on water, \
    we find the essence of being crystallized in ephemeral moments.";
    size_t len = strlen(input);

    uint8_t hash[SHA256_BLOCK_SIZE];
    sha256((uint8_t *)input, len, hash);

    printf("The cryptographic essence of the input is: ");
    print_hex(hash);

    return 0;
}

