#include <netinet/in.h>
#include <arpa/inet.h>

#define BUFFER_SIZE 1024

// Structure to store user information
struct user {
    char name[50];
    char message[1024];
};

// Function to create a socket
int create_socket(void) {
    int sock;
    sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        perror("socket creation failed");
        exit(EXIT_FAILURE);
    }
    return sock;
}

// Function to connect to the server
int connect_to_server(int sock) {
    struct sockaddr_in server_addr;
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(8080);
    inet_pton(AF_INET, "127.0.0.1", &server_addr.sin_addr);
    if (connect(sock, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("connection failed");
        exit(EXIT_FAILURE);
    }
    return sock;
}

// Function to send message to the server
int send_message(int sock, char *message) {
    int len = strlen(message);
    if (send(sock, message, len, 0) < len) {
        perror("message send failed");
        exit(EXIT_FAILURE);
    }
    return sock;
}

// Function to receive message from the server
int receive_message(int sock, char *message, int len) {
    if (recv(sock, message, len, 0) < len) {
        perror("message receive failed");
        exit(EXIT_FAILURE);
    }
    return sock;
}

// Main function
int main(void) {
    int sock = create_socket();
    if (sock < 0) {
        exit(EXIT_FAILURE);
    }

    // Connect to the server
    sock = connect_to_server(sock);
    if (sock < 0) {
        exit(EXIT_FAILURE);
    }

    // Send a message to the server
    char message[] = "Hello, server!";
    send_message(sock, message);

    // Receive a message from the server
    char buffer[BUFFER_SIZE];
    receive_message(sock, buffer, BUFFER_SIZE);

    // Print the received message
    printf("Received message: %s\n", buffer);

    // Close the socket
    close(sock);

    return 0;
}

