#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Structure to represent a task
typedef struct {
    int id; // Unique identifier for the task
    char name[50]; // Name of the task
    int priority; // Priority of the task (1-5)
    int start_time; // Time the task should start
    int end_time; // Time the task should end
    void (*function)(void); // Function to execute when the task is run
} task_t;

// Array to store all tasks
task_t tasks[10];

// Function to add a task to the schedule
void add_task(task_t *task) {
    int i = 0;
    for (i = 0; i < 10; i++) {
        if (tasks[i].id == 0) {
            tasks[i] = *task;
            break;
        }
    }
    if (i == 10) {
        printf("Error: No more space in the schedule\n");
        return;
    }
}

// Function to remove a task from the schedule
void remove_task(int id) {
    int i = 0;
    for (i = 0; i < 10; i++) {
        if (tasks[i].id == id) {
            tasks[i].id = 0;
            break;
        }
    }
}

// Function to check if a task is scheduled
int is_scheduled(int id) {
    int i = 0;
    for (i = 0; i < 10; i++) {
        if (tasks[i].id == id) {
            return 1;
        }
    }
    return 0;
}

// Function to run all tasks with the highest priority
void run_high_priority_tasks() {
    int i = 0;
    for (i = 0; i < 10; i++) {
        if (tasks[i].priority == 1) {
            tasks[i].function();
        }
    }
}

// Function to run all tasks with the specified priority
void run_tasks(int priority) {
    int i = 0;
    for (i = 0; i < 10; i++) {
        if (tasks[i].priority == priority) {
            tasks[i].function();
        }
    }
}

int main() {
    // Add some tasks to the schedule
    task_t task1 = {"Task 1", 1, 10, 15, 20, (void(*)())printf("Task 1 completed\n")};
    task_t task2 = {"Task 2", 2, 15, 20, 25, (void(*)())printf("Task 2 completed\n")};
    task_t task3 = {"Task 3", 3, 20, 25, 30, (void(*)())printf("Task 3 completed\n")};
    add_task(&task1);
    add_task(&task2);
    add_task(&task3);

    // Run all tasks with the highest priority
    run_high_priority_tasks();

    // Run all tasks with priority 2
    run_tasks(2);

    // Remove a task from the schedule
    remove_task(task1.id);

    return 0;
}

