#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Function to swap two elements
void swap(int* a, int* b) {
    int temp = *a;
    *a = *b;
    *b = temp;
}

// Function to sort an array of integers using insertion sort
void sort(int arr[], int n) {
    int i, j, temp;

    // Insertion sort loop
    for (i = 1; i < n; i++) {
        // Find the current element's position in the sorted array
        j = i - 1;

        // While the current element is not in its final position
        while (j >= 0 && arr[j] > arr[i]) {
            // Swap the current element with its previous element
            swap(&arr[j], &arr[i]);

            // Decrease j as we have moved the current element one position to the right
            j--;
        }
    }
}

int main() {
    // Generate a random array of integers
    srand(time(NULL));
    int arr[10] = {rand(), rand(), rand(), rand(), rand(), rand(), rand(), rand(), rand(), rand()};

    // Print the initial array
    printf("Initial array: ");
    for (int i = 0; i < 10; i++) {
        printf("%d ", arr[i]);
    }
    printf("\n");

    // Sort the array using insertion sort
    sort(arr, 10);

    // Print the sorted array
    printf("Sorted array: ");
    for (int i = 0; i < 10; i++) {
        printf("%d ", arr[i]);
    }
    printf("\n");

    return 0;
}

